from transport import *
s=json.loads((ROOT/'state.json').read_text())
script="$root='"+s['root']+r"';$ErrorActionPreference='Stop';$stop=Get-Content -Raw (Join-Path $root 'r9-runtime-stop.json')|ConvertFrom-Json;$own=@($stop.owned_executables);[ordered]@{stop_record_utc=$stop.recorded_utc;probe_never_started=$stop.probe_never_started;owned_executable_count=$own.Count;run_start_exists=$stop.run_start_exists;immutable_manifest_exists=(Test-Path (Join-Path $root 'immutable-inputs-before.json'));cache_copy_exists=(Test-Path (Join-Path $root 'cargo-home/registry'));source_count=@(Get-ChildItem (Join-Path $root 'source') -File -Recurse -Force).Count;progress=$(if(Test-Path (Join-Path $root 'build-progress.json')){Get-Content -Raw (Join-Path $root 'build-progress.json')|ConvertFrom-Json}else{$null});result=$(if(Test-Path (Join-Path $root 'build-result.json')){Get-Content -Raw (Join-Path $root 'build-result.json')|ConvertFrom-Json|Select-Object passed,steps}else{$null});freeze_exists=(Test-Path (Join-Path $root 'freeze.json'))}|ConvertTo-Json -Depth 12"
r,out=remote('state-after-stop',script,timeout=55,exe='pwsh.exe');print(r);print(out)
